window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-aafd62474fbdabc0"]={"versions": [{"id": "FIG-aafd62474fbdabc0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zählerdiagramm zur Veranschaulichung eines fehlschlagenden Compare-Match-Vorgangs im AUTOSAR OCU-Treiber (Output Compare Unit, MCAL-Schicht im Basic Software Architecture Stack). Das Diagramm stellt das zeitliche Verhalten und die Registerwerte bei verspäteter Schwellwertprogrammierung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Freilaufendes Hardware-Zählregister, dargestellt mit diskreten diskontinuierlichen Zählwerten von 29 bis 39 und fortlaufend (...).</li>\n<li><strong>Reference Value</strong>: Basis- bzw. Startreferenzwert (im Beispiel mit Wert 30 gekennzeichnet, farblich grün korreliert mit den Zählerständen 30 bis 34).</li>\n<li><strong>Compare threshold</strong>: Zu programmierender Ziel-Schwellwert (Wert 35, dargestellt in rotem/rosa Kasten).</li>\n<li><strong>Next value used for the compare process, when the threshold is actually written</strong>: Zeiger/Indikator auf Zählerstand 36, an dem der Schwellwert physisch wirksam in das Hardware-Register geschrieben wird.</li>\n<li><strong>Doppelpfeil-Vergleich</strong>: Indiziert den beabsichtigten Vergleich zwischen Schwellwert 35 und Zählerstand 35.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Zähler läuft kontinuierlich inkrementierend beginnend vor 29.</li>\n<li>Bei Zählerstand 30 liegt der Referenzwert vor; die Software beabsichtigt, einen Schwellwert von 35 zu setzen (Intervall 30 bis 34 als Vorlauf).</li>\n<li>Durch Verarbeitungs- oder Schreiblatenzen wird der <code>Compare threshold</code> (35) erst physisch wirksam ins Register geschrieben, wenn der freilaufende Zähler bereits den Wert 36 erreicht hat.</li>\n<li>Da der Zielwert 35 zeitlich bereits überschritten wurde, tritt in diesem Zählerzyklus keine Gleichheit (<code>equality</code>) zwischen Schwellwert und Zähler auf; ein Match bleibt aus, bis der Zähler den gesamten Wertebereich durchlaufen hat und überläuft.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Kritisches Timing-Szenario für MCAL-Treiberentwickler und OCU-Anwender:</p>\n<ul class=\"fig-list\">\n<li>Beim Konfigurieren relativer Schwellwerte über OCU-APIs muss sichergestellt sein, dass die Zeitspanne zwischen Auslesen/Festlegen des Referenzwerts und dem tatsächlichen Hardware-Schreibvorgang (<code>threshold actually written</code>) kürzer ist als die Differenz zum Zielschwellwert.</li>\n<li>Liegt der Zählerstand beim Registerzugriff bereits strikt über dem Zielschwellwert, greift der Gleichheitsvergleich der Hardwarekomparatoren (<code>counter == threshold</code>) nicht mehr. Treiber- und Anwendungslogik müssen solche Randbedingungen durch minimale Distanzen oder Software-Checks abfangen.</li>\n</ul>"}, {"id": "FIG-b14e14104f8da58a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zählerdiagramm zur Veranschaulichung eines fehlschlagenden Compare-Match-Vorgangs im AUTOSAR OCU-Treiber (Output Compare Unit, MCAL-Schicht im Basic Software Architecture Stack). Das Diagramm stellt das zeitliche Verhalten und die Registerwerte bei verspäteter Schwellwertprogrammierung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Freilaufendes Hardware-Zählregister, dargestellt mit diskreten diskontinuierlichen Zählwerten von 29 bis 39 und fortlaufend (...).</li>\n<li><strong>Reference Value</strong>: Basis- bzw. Startreferenzwert (im Beispiel mit Wert 30 gekennzeichnet, farblich grün korreliert mit den Zählerständen 30 bis 34).</li>\n<li><strong>Compare threshold</strong>: Zu programmierender Ziel-Schwellwert (Wert 35, dargestellt in rotem/rosa Kasten).</li>\n<li><strong>Next value used for the compare process, when the threshold is actually written</strong>: Zeiger/Indikator auf Zählerstand 36, an dem der Schwellwert physisch wirksam in das Hardware-Register geschrieben wird.</li>\n<li><strong>Doppelpfeil-Vergleich</strong>: Indiziert den beabsichtigten Vergleich zwischen Schwellwert 35 und Zählerstand 35.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Zähler läuft kontinuierlich inkrementierend beginnend vor 29.</li>\n<li>Bei Zählerstand 30 liegt der Referenzwert vor; die Software beabsichtigt, einen Schwellwert von 35 zu setzen (Intervall 30 bis 34 als Vorlauf).</li>\n<li>Durch Verarbeitungs- oder Schreiblatenzen wird der <code>Compare threshold</code> (35) erst physisch wirksam ins Register geschrieben, wenn der freilaufende Zähler bereits den Wert 36 erreicht hat.</li>\n<li>Da der Zielwert 35 zeitlich bereits überschritten wurde, tritt in diesem Zählerzyklus keine Gleichheit (<code>equality</code>) zwischen Schwellwert und Zähler auf; ein Match bleibt aus, bis der Zähler den gesamten Wertebereich durchlaufen hat und überläuft.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Kritisches Timing-Szenario für MCAL-Treiberentwickler und OCU-Anwender:</p>\n<ul class=\"fig-list\">\n<li>Beim Konfigurieren relativer Schwellwerte über OCU-APIs muss sichergestellt sein, dass die Zeitspanne zwischen Auslesen/Festlegen des Referenzwerts und dem tatsächlichen Hardware-Schreibvorgang (<code>threshold actually written</code>) kürzer ist als die Differenz zum Zielschwellwert.</li>\n<li>Liegt der Zählerstand beim Registerzugriff bereits strikt über dem Zielschwellwert, greift der Gleichheitsvergleich der Hardwarekomparatoren (<code>counter == threshold</code>) nicht mehr. Treiber- und Anwendungslogik müssen solche Randbedingungen durch minimale Distanzen oder Software-Checks abfangen.</li>\n</ul>"}, {"id": "FIG-33ee80274f7c045c", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zählerdiagramm zur Veranschaulichung eines fehlschlagenden Compare-Match-Vorgangs im AUTOSAR OCU-Treiber (Output Compare Unit, MCAL-Schicht im Basic Software Architecture Stack). Das Diagramm stellt das zeitliche Verhalten und die Registerwerte bei verspäteter Schwellwertprogrammierung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Freilaufendes Hardware-Zählregister, dargestellt mit diskreten diskontinuierlichen Zählwerten von 29 bis 39 und fortlaufend (...).</li>\n<li><strong>Reference Value</strong>: Basis- bzw. Startreferenzwert (im Beispiel mit Wert 30 gekennzeichnet, farblich grün korreliert mit den Zählerständen 30 bis 34).</li>\n<li><strong>Compare threshold</strong>: Zu programmierender Ziel-Schwellwert (Wert 35, dargestellt in rotem/rosa Kasten).</li>\n<li><strong>Next value used for the compare process, when the threshold is actually written</strong>: Zeiger/Indikator auf Zählerstand 36, an dem der Schwellwert physisch wirksam in das Hardware-Register geschrieben wird.</li>\n<li><strong>Doppelpfeil-Vergleich</strong>: Indiziert den beabsichtigten Vergleich zwischen Schwellwert 35 und Zählerstand 35.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Zähler läuft kontinuierlich inkrementierend beginnend vor 29.</li>\n<li>Bei Zählerstand 30 liegt der Referenzwert vor; die Software beabsichtigt, einen Schwellwert von 35 zu setzen (Intervall 30 bis 34 als Vorlauf).</li>\n<li>Durch Verarbeitungs- oder Schreiblatenzen wird der <code>Compare threshold</code> (35) erst physisch wirksam ins Register geschrieben, wenn der freilaufende Zähler bereits den Wert 36 erreicht hat.</li>\n<li>Da der Zielwert 35 zeitlich bereits überschritten wurde, tritt in diesem Zählerzyklus keine Gleichheit (<code>equality</code>) zwischen Schwellwert und Zähler auf; ein Match bleibt aus, bis der Zähler den gesamten Wertebereich durchlaufen hat und überläuft.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Kritisches Timing-Szenario für MCAL-Treiberentwickler und OCU-Anwender:</p>\n<ul class=\"fig-list\">\n<li>Beim Konfigurieren relativer Schwellwerte über OCU-APIs muss sichergestellt sein, dass die Zeitspanne zwischen Auslesen/Festlegen des Referenzwerts und dem tatsächlichen Hardware-Schreibvorgang (<code>threshold actually written</code>) kürzer ist als die Differenz zum Zielschwellwert.</li>\n<li>Liegt der Zählerstand beim Registerzugriff bereits strikt über dem Zielschwellwert, greift der Gleichheitsvergleich der Hardwarekomparatoren (<code>counter == threshold</code>) nicht mehr. Treiber- und Anwendungslogik müssen solche Randbedingungen durch minimale Distanzen oder Software-Checks abfangen.</li>\n</ul>"}, {"id": "FIG-dcc3a001be4fe94a", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Timing- und Zählerdiagramm zur Veranschaulichung eines fehlschlagenden Compare-Match-Vorgangs im AUTOSAR OCU-Treiber (Output Compare Unit, MCAL-Schicht im Basic Software Architecture Stack). Das Diagramm stellt das zeitliche Verhalten und die Registerwerte bei verspäteter Schwellwertprogrammierung dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Free running counter</strong>: Freilaufendes Hardware-Zählregister, dargestellt mit diskreten diskontinuierlichen Zählwerten von 29 bis 39 und fortlaufend (...).</li>\n<li><strong>Reference Value</strong>: Basis- bzw. Startreferenzwert (im Beispiel mit Wert 30 gekennzeichnet, farblich grün korreliert mit den Zählerständen 30 bis 34).</li>\n<li><strong>Compare threshold</strong>: Zu programmierender Ziel-Schwellwert (Wert 35, dargestellt in rotem/rosa Kasten).</li>\n<li><strong>Next value used for the compare process, when the threshold is actually written</strong>: Zeiger/Indikator auf Zählerstand 36, an dem der Schwellwert physisch wirksam in das Hardware-Register geschrieben wird.</li>\n<li><strong>Doppelpfeil-Vergleich</strong>: Indiziert den beabsichtigten Vergleich zwischen Schwellwert 35 und Zählerstand 35.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Der Zähler läuft kontinuierlich inkrementierend beginnend vor 29.</li>\n<li>Bei Zählerstand 30 liegt der Referenzwert vor; die Software beabsichtigt, einen Schwellwert von 35 zu setzen (Intervall 30 bis 34 als Vorlauf).</li>\n<li>Durch Verarbeitungs- oder Schreiblatenzen wird der <code>Compare threshold</code> (35) erst physisch wirksam ins Register geschrieben, wenn der freilaufende Zähler bereits den Wert 36 erreicht hat.</li>\n<li>Da der Zielwert 35 zeitlich bereits überschritten wurde, tritt in diesem Zählerzyklus keine Gleichheit (<code>equality</code>) zwischen Schwellwert und Zähler auf; ein Match bleibt aus, bis der Zähler den gesamten Wertebereich durchlaufen hat und überläuft.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Kritisches Timing-Szenario für MCAL-Treiberentwickler und OCU-Anwender:</p>\n<ul class=\"fig-list\">\n<li>Beim Konfigurieren relativer Schwellwerte über OCU-APIs muss sichergestellt sein, dass die Zeitspanne zwischen Auslesen/Festlegen des Referenzwerts und dem tatsächlichen Hardware-Schreibvorgang (<code>threshold actually written</code>) kürzer ist als die Differenz zum Zielschwellwert.</li>\n<li>Liegt der Zählerstand beim Registerzugriff bereits strikt über dem Zielschwellwert, greift der Gleichheitsvergleich der Hardwarekomparatoren (<code>counter == threshold</code>) nicht mehr. Treiber- und Anwendungslogik müssen solche Randbedingungen durch minimale Distanzen oder Software-Checks abfangen.</li>\n</ul>"}], "trans": [{"from": "FIG-aafd62474fbdabc0", "to": "FIG-b14e14104f8da58a", "fr": "R4.1.3", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b14e14104f8da58a", "to": "FIG-33ee80274f7c045c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-33ee80274f7c045c", "to": "FIG-dcc3a001be4fe94a", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
